style.css:
@-moz-document regexp("(?!http://www\.youtube\.com).*") {
/* --- Text Color Styling (Neon Green) --- */

/* Body text color */
body {
  color: #39FF14; /* Neon green for general body text */
}

/* Heading text colors */
h1, h2, h3, h4, h5, h6 {
  color: #39FF14; /* Neon green for headings */
}

/* Paragraph text color */
p {
  color: #39FF14; /* Neon green for paragraph text */
  }
}
